
const B64 = "";
const bytes = Uint8Array.from(atob(B64), c => c.charCodeAt(0));

Deno.serve((req) => {
  const common = {
    "Access-Control-Allow-Origin": "*",
    "Accept-Ranges": "bytes",
    "Cache-Control": "public, max-age=3600",
    "Content-Type": "video/webm",
  };
  if (req.method === "OPTIONS") return new Response(null,{status:204,headers:common});
  if (req.method === "HEAD") return new Response(null,{status:200,headers:{...common,"Content-Length":String(bytes.length)}});
  const range = req.headers.get("range");
  if (range) {
    const m = /^bytes=(\d+)-(\d*)$/.exec(range);
    if (m) {
      const start = Math.min(Number(m[1]), bytes.length - 1);
      const end = m[2] ? Math.min(Number(m[2]), bytes.length - 1) : bytes.length - 1;
      const body = bytes.slice(start, end + 1);
      return new Response(body,{status:206,headers:{
        ...common,
        "Content-Length":String(body.length),
        "Content-Range":`bytes ${start}-${end}/${bytes.length}`
      }});
    }
  }
  return new Response(bytes,{status:200,headers:{...common,"Content-Length":String(bytes.length)}});
});
